/* eslint eslint-comments/no-use: off */
import type {DeploymentData} from '../types/list'
import {RelativeTime} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {LinkExternalIcon} from '@primer/octicons-react'
import {testIdProps} from '@github-ui/test-id-props'
import {GitRef} from './list-components/GitRef'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'

import styles from './DeploymentListItemMetadata.module.css'

type DeploymentListItemMetadataProps = Pick<
  DeploymentData,
  | 'owner'
  | 'gitRef'
  | 'refExists'
  | 'repo'
  | 'sha'
  | 'pullRequestID'
  | 'pullRequestPath'
  | 'prefix'
  | 'environmentURL'
  | 'environment'
> & {
  createdAt?: DeploymentData['createdAt']
}

export const DeploymentListItemMetadata = ({
  owner,
  gitRef,
  refExists,
  repo,
  sha,
  pullRequestID,
  pullRequestPath,
  prefix,
  createdAt,
  environmentURL,
  environment,
}: DeploymentListItemMetadataProps) => (
  <>
    {gitRef && (
      <ListItemMetadata variant="primary" className={styles.ListItemMetadata_0}>
        <GitRef
          owner={owner}
          repo={repo}
          gitRef={gitRef}
          refExists={refExists}
          sha={sha}
          pullRequestID={pullRequestID}
          pullRequestPath={pullRequestPath}
          prefix={prefix}
        />
      </ListItemMetadata>
    )}
    <ListItemMetadata alignment="right" className={styles.ListItemMetadata_1}>
      <RelativeTime datetime={createdAt} format="relative" prefix="" />
    </ListItemMetadata>
    <ListItemMetadata
      alignment="right"
      aria-label={environmentURL && `View deployment to ${environment}`}
      className={styles.ListItemMetadata_2}
    >
      {environmentURL && (
        <a
          href={environmentURL}
          aria-label={`View deployment to ${environment}`}
          {...testIdProps('deployments-list-environment-url')}
        >
          <Octicon icon={LinkExternalIcon} sx={{color: 'fg.subtle'}} />
        </a>
      )}
    </ListItemMetadata>
  </>
)

try{ DeploymentListItemMetadata.displayName ||= 'DeploymentListItemMetadata' } catch {}